item.text:
{
  "repair_case_id": "RC-0103",
  "role": "power_nonrecurrence_auditor",
  "role_contract_version": "0.1.0",
  "findings": [
    {
      "finding_id": "F1",
      "statement": "H1 is established; H2–H4 are substantially established. Institutional responsibility is established, but particular individuals' responsibility remains attributed pending evidence or qualifying disclosure. The packet supplies no independently verified case records.",
      "basis": "packet",
      "harm_ids": ["H1", "H2", "H3", "H4"],
      "materiality": "decisive"
    },
    {
      "finding_id": "F2",
      "statement": "Conditional individual amnesty can contribute to a defensible repair package, but is not itself reparation or exoneration. Its justification requires demonstrated disclosure benefits, narrowly bounded eligibility, independent review and effective alternatives when conditions fail; political convenience is insufficient.",
      "basis": "constitutional_interpretation",
      "harm_ids": ["H2", "H3", "H4"],
      "materiality": "decisive"
    },
    {
      "finding_id": "F3",
      "statement": "Institutions implicated in abuses must not control appointments, access to evidence or review of their own conduct. State-led repair remains permissible with independent decision-makers, protected funding, conflict rules and external challenge.",
      "basis": "constitutional_interpretation",
      "harm_ids": ["H1", "H4"],
      "materiality": "decisive"
    },
    {
      "finding_id": "F4",
      "statement": "The packet does not establish who sets eligibility and archive rules, appoints commissioners, verifies disclosures, funds reparations or enforces reform. These omissions prevent a finding that the proposed design already meets the required safeguards.",
      "basis": "missing_information",
      "harm_ids": ["H2", "H4"],
      "materiality": "high"
    },
    {
      "finding_id": "F5",
      "statement": "Victims disagree about amnesty. Participation must include dissenters and people unable or unwilling to testify publicly. Witnesses, whistleblowers and people accused in testimony also need explicit protection and procedural standing; their interests are not separately developed in the packet.",
      "basis": "inference",
      "harm_ids": ["H1", "H2"],
      "materiality": "high"
    },
    {
      "finding_id": "F6",
      "statement": "Disclosure incentives may unlock hidden evidence, but their effectiveness and long-term effects remain unknown. Amnesty without credible investigation and prosecution of nonqualifying cases could reward strategic concealment.",
      "basis": "inference",
      "harm_ids": ["H2", "H3", "H4"],
      "materiality": "high"
    },
    {
      "finding_id": "F7",
      "statement": "Non-recurrence requires changes to institutional authority and practice, with measurable implementation and independent monitoring. Future protection cannot replace current victims' repair, and no institutional reform can restore lives lost.",
      "basis": "constitutional_interpretation",
      "harm_ids": ["H1", "H4"],
      "materiality": "high"
    }
  ],
  "principle_assessments": [
    {
      "principle_id": "MC-01",
      "status": "conflict",
      "reason": "Peace serves persons, but using victims' lost remedies merely as the price of national unity would instrumentalise them."
    },
    {
      "principle_id": "MC-02",
      "status": "supports_component",
      "reason": "Protection, rehabilitation and institutional reform address continuing suffering and recurrence; claimed peace benefits still require evidence."
    },
    {
      "principle_id": "MC-03",
      "status": "supports_component",
      "reason": "Victims need meaningful choices over testimony, privacy, treatment and reconciliation, without forfeiting repair."
    },
    {
      "principle_id": "MC-04",
      "status": "supports_component",
      "reason": "Independent corroboration, preserved records and explicit uncertainty prevent negotiated narratives from replacing truth."
    },
    {
      "principle_id": "MC-05",
      "status": "concern",
      "reason": "Eligibility must apply consistently across political affiliations and ranks without collective guilt or flattening differences in institutional responsibility."
    },
    {
      "principle_id": "MC-06",
      "status": "supports_component",
      "reason": "Funded representation, accessible participation and protection counter victims' low power."
    },
    {
      "principle_id": "MC-07",
      "status": "conflict",
      "reason": "Society receives transition benefits while victims may lose prosecution opportunities; public funding and enforceable repair must prevent exporting all costs to them."
    },
    {
      "principle_id": "MC-08",
      "status": "supports_component",
      "reason": "Truth, restitution, compensation and rehabilitation support repair, but mercy requires accountability and protection against repetition."
    },
    {
      "principle_id": "MC-09",
      "status": "supports_component",
      "reason": "Durable oversight and reliable archives protect future generations against renewed abuse and official denial."
    },
    {
      "principle_id": "MC-10",
      "status": "concern",
      "reason": "Investigatory powers and protective restrictions require necessity, proportionality and review; transitional authority must not become unchecked permanent power."
    },
    {
      "principle_id": "MC-11",
      "status": "supports_component",
      "reason": "Independent appointments, reasoned decisions, appeals and enforceable remedies are essential where institutions assess predecessor abuses."
    },
    {
      "principle_id": "MC-12",
      "status": "supports_component",
      "reason": "Preserve criticism of amnesty, disputed findings and the national narrative, with correction procedures as evidence emerges."
    }
  ],
  "component_assessments": [
    {
      "component_type": "truth_acknowledgement",
      "status": "required",
      "reason": "R1 needs independent investigators, lawful evidence access, corroboration and reasoned findings distinguishing established facts from allegations. Protect confidential testimony and provide opportunities to challenge adverse findings.",
      "option_ids": ["R1"]
    },
    {
      "component_type": "amnesty",
      "status": "permissible",
      "reason": "R2 is defensible only conditionally: published narrow criteria, application-specific political nexus findings, scrutiny of private motives, full material disclosure independently tested, and precise identification of covered acts. Require victim notice, representation and challenge, independent appeal, and predefined revocation for material deception or concealment with due process. Political labelling alone cannot qualify an act; amnesty cannot cover future wrongdoing or erase findings.",
      "option_ids": ["R2"]
    },
    {
      "component_type": "accountability",
      "status": "required",
      "reason": "Resource independent investigation and evidence-supported prosecution or civil proceedings for nonapplicants, refused applicants and uncovered acts. Preserve fair trial rights; refusal of amnesty is not proof of guilt. Define amnesty's legal effects publicly and preserve effective victim remedies.",
      "option_ids": ["R3"]
    },
    {
      "component_type": "protection",
      "status": "required",
      "reason": "Provide accessible witness protection, confidential reporting, anti-retaliation enforcement and trauma-sensitive participation. Protection must extend to people criticising the process.",
      "option_ids": ["R1", "R5", "R7"]
    },
    {
      "component_type": "compensation",
      "status": "required",
      "reason": "Establish funded, timely reparation with transparent eligibility, fair allocation under finite resources and independent appeal. Account for state-created evidence gaps; do not condition payment on testimony, amnesty acceptance or forgiveness.",
      "option_ids": ["R4"]
    },
    {
      "component_type": "rehabilitation",
      "status": "required",
      "reason": "Deliver voluntary medical, psychological and social support independently of public participation or reconciliation. Test availability and accessibility rather than counting referrals alone.",
      "option_ids": ["R5"]
    },
    {
      "component_type": "restitution",
      "status": "required",
      "reason": "Pursue feasible recovery of remains, records, property and legal status with family participation and reviewable decisions. Explain impossibility without treating it as discharge of all repair duties.",
      "option_ids": ["R6"]
    },
    {
      "component_type": "institutional_reform",
      "status": "required",
      "reason": "R7 requires independent civilian oversight, protected complaints, evidence-preservation duties and review of abusive commands and practices. Any personnel exclusion must rest on individual evidence, role-related risk and appeal rather than prior affiliation.",
      "option_ids": ["R7"]
    },
    {
      "component_type": "non_recurrence",
      "status": "required",
      "reason": "Assign responsible bodies, budgets and deadlines; independently report on retaliation, disclosure verification, accountability referrals, reparation delivery and institutional compliance. Persistent failure must trigger corrective action rather than ceremonial closure.",
      "option_ids": ["R3", "R7"]
    },
    {
      "component_type": "memorialisation",
      "status": "recommended",
      "reason": "Use independently governed archives with preservation duties, transparent access and redaction rules, correction mechanisms and review of secrecy decisions. Include victim dissent without compelling publication of sensitive testimony.",
      "option_ids": ["R8"]
    },
    {
      "component_type": "reconciliation",
      "status": "permissible",
      "reason": "R9 must remain voluntary and distinct from truth findings, legal accountability and repair. Rejecting forgiveness must carry no loss of rights or public standing.",
      "option_ids": ["R9"]
    },
    {
      "component_type": "other",
      "status": "insufficient_evidence",
      "reason": "R10 remains a serious comparator. The packet establishes prosecution constraints but not that conditional amnesty is necessary in every case or superior overall; compare attainable accountability and disclosure before limiting remedies.",
      "option_ids": ["R10"]
    }
  ],
  "failure_risks": [
    {
      "risk": "revenge",
      "status": "possible",
      "reason": "Public accusation or institutional vetting could become humiliation or punishment without proof; require individual evidence and review."
    },
    {
      "risk": "impunity",
      "status": "serious",
      "reason": "Unverified disclosure, broad political criteria or unfunded prosecution could convert conditional amnesty into practical blanket immunity."
    },
    {
      "risk": "forced_forgiveness",
      "status": "serious",
      "reason": "The packet identifies reconciliation pressure; protect refusal and separate all benefits from forgiveness."
    },
    {
      "risk": "inherited_or_category_guilt",
      "status": "possible",
      "reason": "Institutional responsibility must not become guilt assigned to every former official, citizen or organisation member."
    },
    {
      "risk": "symbolic_only_repair",
      "status": "serious",
      "reason": "Collecting testimony without funded material repair would extract public benefit while leaving victims' needs unmet."
    },
    {
      "risk": "victim_voice_erasure",
      "status": "serious",
      "reason": "Elite bargains or selected representatives could obscure disagreement and exclude private or nonparticipating victims."
    },
    {
      "risk": "unsafe_reintegration",
      "status": "possible",
      "reason": "Amnesty does not establish fitness for security authority or absence of present danger; review current risks through separate fair procedures."
    },
    {
      "risk": "other",
      "status": "serious",
      "reason": "Institutional capture of appointments, records or budgets could allow implicated bodies effectively to judge themselves and obstruct reform."
    }
  ],
  "recommended_components": [
    "R1 with independent governance, evidence verification and protected victim participation.",
    "R2 only under narrow, reviewable conditions and a demonstrated justification for limiting accountability.",
    "R3 with independent capacity and credible follow-through when amnesty does not apply.",
    "R4, R5 and R6 with funded delivery, fair eligibility and accessible remedies.",
    "R7 with enforceable oversight, individualised personnel review and published implementation monitoring.",
    "R8 with independent archive governance and privacy safeguards.",
    "R9 only as voluntary reconciliation without any forgiveness requirement."
  ],
  "information_requests": [
    "Who appoints and can remove commissioners, controls budgets, sets eligibility rules and hears appeals?",
    "What independent investigative capacity, record access and disclosure-testing procedures are available?",
    "What precisely does amnesty extinguish, and what remedies remain for victims?",
    "How will political nexus, mixed motives and material nondisclosure be adjudicated?",
    "What funded prosecution, reparation and reform commitments have enforceable deadlines?",
    "How will diverse victims, families, dissenters and people unable to testify influence governance and challenge decisions?"
  ],
  "evidence_that_could_change_view": [
    "Evidence that substantial disclosure is obtainable without amnesty would weaken the justification for limiting prosecution.",
    "Independently corroborated disclosures that recover otherwise inaccessible truth would strengthen the conditional case for R2.",
    "Selective grants, tolerated concealment, retaliation or political obstruction of prosecutions would undermine legitimacy.",
    "Victim participation showing exclusion or coercion would require redesign, without treating any single group as speaking for all victims.",
    "Verified delivery of reparations and institutional reform would strengthen the package; persistent nonimplementation would weaken it."
  ],
  "unresolved_objections": [
    "The strongest objection is that even a fair, truthful process can permanently deny some victims prosecution for grave violations they never agreed to trade away. Public benefits and compensation do not eliminate that loss or demonstrate that the bargain treats them fairly.",
    "Those who possess concealed evidence gain bargaining power from wrongdoing; independent verification and credible prosecution constrain but cannot fully remove this asymmetry.",
    "The packet cannot establish whether disclosure and non-recurrence benefits outweigh the loss of accountability within the protected moral constraints. Conditional endorsement therefore does not certify the actual design."
  ]
}
